import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"sdkgen-c backend ownership","description":"","frontmatter":{"title":"`sdkgen-c` backend ownership","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"accepted","status_note":"Accepted — extracted in ADR-0128 Phase 2 (`modules/sdkgen-c`)."},"headers":[],"relativePath":"c/project/adrs/0136-sdkgen-c-backend-ownership.md","filePath":"vendored/c/project/adrs/0136-sdkgen-c-backend-ownership.md"}'),a={name:`c/project/adrs/0136-sdkgen-c-backend-ownership.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0136-sdkgen-c-backend-ownership" tabindex="-1">ADR-0136: <code>sdkgen-c</code> backend ownership <a class="header-anchor" href="#adr-0136-sdkgen-c-backend-ownership" aria-label="Permalink to “ADR-0136: sdkgen-c backend ownership”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./../0107-handl-sdk-generator.html">ADR-0107</a> defines the SDK generator as a port: <code>SdkgenBackend</code> → <code>SdkgenModule</code> → <code>Emitter</code>, with a <em>target record</em><code>(backend_id, emitter_id)</code>. Today the dispatcher in <code>plugin-ext-sdkgen</code> hard-codes <code>if kind != &quot;c&quot; &amp;&amp; …</code> plus a <code>match</code> arm per target.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>c</code> owns the <strong>C backend</strong>: <code>plugin-sdkgen-backend-c</code> — the C ABI model, the header/<code>clang-sys</code> layer, and the C-specific emitter primitives — plus the platform C-binding ADRs (<a href="./../0110-handl-sdkgen-windows-macos.html">ADR-0110</a>, <a href="./../0111-handl-sdkgen-jvm.html">ADR-0111</a>, <a href="./../0112-handl-sdkgen-bukkit-spigot-paper.html">ADR-0112</a>) and the <code>-c</code> package block with its <code>generated/*-c-linux-x86_64/</code> outputs.</p><p><code>host</code> keeps the port (<code>SdkgenTarget</code> descriptor + registry) and the cross-cutting <code>plugin-sdkgen</code> IR / <code>plugin-sdkgen-emitter-file</code>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>clang-sys</code> leaves the platform lock and build.</li><li><code>python</code> depends on this module at <em>target</em> level: <code>hnl sdkgen python</code> is backend <code>c</code> + emitter <code>python</code>, so the registry key is the target record, not a crate.</li><li>Adding a C-family target is an edit here plus a registry entry in the consuming host — never a change to the platform dispatcher.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};